mapper.select:
SELECT

FROM delivery_route r WHERE r.deleted=FALSE
AND (r.route_name ILIKE concat('%',#{q.keyword},'%') OR
    r.route_no ILIKE concat('%',#{q.keyword},'%'))

AND r.delivery_date=#{q.deliveryDate}
AND r.status=#{q.status}
AND r.warehouse_id=#{q.warehouseId}
AND r.driver_id=#{q.driverId}
AND r.vehicle_id=#{q.vehicleId}

    AND EXISTS (SELECT 1 FROM delivery_route_stop s WHERE s.route_id=r.id AND s.deleted=FALSE
    AND s.province_code=#{q.provinceCode}
    AND s.city_code=#{q.cityCode}
    AND s.district_code=#{q.districtCode})


ORDER BY r.delivery_date DESC,r.id DESC

SELECT * FROM () c WHERE c.status IN
#{status}
AND NOT EXISTS (SELECT 1 FROM delivery_route_order d WHERE d.order_id=c.order_id AND
d.assignment_status='ACTIVE' AND d.deleted=FALSE)
AND (c.order_no ILIKE concat('%',#{q.keyword},'%') OR
    c.customer_name ILIKE concat('%',#{q.keyword},'%') OR c.address ILIKE concat('%',#{q.keyword},'%'))

AND c.customer_name ILIKE
    concat('%',#{q.customerKeyword},'%')

AND (c.expect_delivery_time AT TIME ZONE
    'Asia/Shanghai')::date=#{q.deliveryDate}

AND c.expect_delivery_time >= #{q.deliveryTimeFrom}
AND c.expect_delivery_time <= #{q.deliveryTimeTo}
AND c.customer_id=#{q.customerId}
AND c.province_code=#{q.provinceCode}
AND c.city_code=#{q.cityCode}
AND c.district_code=#{q.districtCode}
AND c.order_amount >= #{q.minAmount}
AND c.order_amount <= #{q.maxAmount}
AND c.item_count >= #{q.minItemCount}
AND c.item_count <= #{q.maxItemCount}
AND c.longitude IS NOT NULL AND c.latitude IS NOT NULL AND
    c.geom_crs IS NOT NULL


AND FALSE
ORDER BY c.expect_delivery_time NULLS LAST,c.order_id

