UPDATE delivery_route_order
SET print_count=print_count + 1, last_printed_at=now(), last_printed_by=#{operator}, updated_at=now(), updated_by=#{operator}
WHERE deleted = FALSE
  AND assignment_status = 'ACTIVE'
  AND id IN
#{id}
